import sympy
from sympy import eye, zeros

I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

CONDITION_LABELS = [
    "H_1: R is a ring",
    "H_2: I is the principal two-sided ideal generated by e",
    "¬Q: The quotient ring R/I is not isomorphic to the ring R(1-e)"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    try:
        if len(witness) == 3:
            R, I, e = witness
        elif len(witness) == 2:
            R, e = witness
            I = None
        else:
            return [False, False, False]
    except Exception:
        return [False, False, False]

    def get_idx(lst, elem):
        for i, x in enumerate(lst):
            if x == elem:
                return i
        return -1

    def check_H1():
        if not R: return False
        for x in R:
            for y in R:
                if get_idx(R, x + y) == -1: return False
                if get_idx(R, x * y) == -1: return False
                
        has_zero = False
        zero = None
        for z in R:
            if all(get_idx(R, z + x) == get_idx(R, x) and get_idx(R, x + z) == get_idx(R, x) for x in R):
                has_zero = True
                zero = z
                break
        if not has_zero: return False
        
        for x in R:
            has_inv = False
            for y in R:
                if x + y == zero and y + x == zero:
                    has_inv = True
                    break
            if not has_inv: return False
            
        for x in R:
            for y in R:
                if x + y != y + x: return False
                for z in R:
                    if (x + y) + z != x + (y + z): return False
                    if (x * y) * z != x * (y * z): return False
                    if x * (y + z) != x * y + x * z: return False
                    if (x + y) * z != x * z + y * z: return False
        return True

    try:
        h1 = check_H1()
    except Exception:
        h1 = False

    def check_H2():
        nonlocal I
        if get_idx(R, e) == -1: return False
        
        zero = None
        for z in R:
            if all(get_idx(R, z + x) == get_idx(R, x) for x in R):
                zero = z
                break
        if zero is None: return False
        
        gen = [e]
        changed = True
        while changed:
            changed = False
            new_gen = list(gen)
            for x in gen:
                for y in gen:
                    if get_idx(new_gen, x + y) == -1:
                        new_gen.append(x + y)
                        changed = True
                for inv in R:
                    if x + inv == zero:
                        if get_idx(new_gen, inv) == -1:
                            new_gen.append(inv)
                            changed = True
                        break
                for r in R:
                    if get_idx(new_gen, r * x) == -1:
                        new_gen.append(r * x)
                        changed = True
                    if get_idx(new_gen, x * r) == -1:
                        new_gen.append(x * r)
                        changed = True
            gen = new_gen
            
        if I is None:
            I = gen
            return True
        else:
            if not all(get_idx(R, x) != -1 for x in I): return False
            for x in I:
                if get_idx(gen, x) == -1: return False
            for x in gen:
                if get_idx(I, x) == -1: return False
            return True

    try:
        h2 = check_H2()
    except Exception:
        h2 = False

    def check_neg_Q():
        if not h1 or not h2: return False
        
        id_R = None
        for x in R:
            if all(get_idx(R, x * y) == get_idx(R, y) and get_idx(R, y * x) == get_idx(R, y) for y in R):
                id_R = x
                break
        if id_R is None:
            return True
            
        zero = None
        for z in R:
            if all(get_idx(R, z + x) == get_idx(R, x) for x in R):
                zero = z
                break
                
        inv_e = None
        for y in R:
            if e + y == zero:
                inv_e = y
                break
        if inv_e is None: return True
        
        f = id_R + inv_e
        
        S = []
        for r in R:
            val = r * f
            if get_idx(S, val) == -1:
                S.append(val)
                
        for x in S:
            for y in S:
                if get_idx(S, x + y) == -1: return True
                if get_idx(S, x * y) == -1: return True
                
        cosets = []
        for r in R:
            coset = []
            for i in I:
                coset.append(r + i)
            is_new = True
            for c in cosets:
                if len(c) == len(coset) and all(get_idx(c, x) != -1 for x in coset):
                    is_new = False
                    break
            if is_new:
                cosets.append(coset)
                
        if len(cosets) != len(S):
            return True
            
        def get_coset_idx(c):
            for i, c2 in enumerate(cosets):
                if len(c2) == len(c) and all(get_idx(c2, x) != -1 for x in c):
                    return i
            return -1
            
        n = len(cosets)
        add1 = [[0]*n for _ in range(n)]
        mul1 = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                rep1 = cosets[i][0]
                rep2 = cosets[j][0]
                sum_rep = rep1 + rep2
                mul_rep = rep1 * rep2
                
                sum_coset = [sum_rep + x for x in I]
                mul_coset = [mul_rep + x for x in I]
                
                idx_sum = get_coset_idx(sum_coset)
                idx_mul = get_coset_idx(mul_coset)
                
                if idx_sum == -1 or idx_mul == -1:
                    return True
                
                add1[i][j] = idx_sum
                mul1[i][j] = idx_mul
                
        add2 = [[0]*n for _ in range(n)]
        mul2 = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                idx_sum = get_idx(S, S[i] + S[j])
                idx_mul = get_idx(S, S[i] * S[j])
                if idx_sum == -1 or idx_mul == -1:
                    return True
                add2[i][j] = idx_sum
                mul2[i][j] = idx_mul
                
        z1 = None
        for i in range(n):
            if all(add1[i][j] == j for j in range(n)):
                z1 = i; break
        z2 = None
        for i in range(n):
            if all(add2[i][j] == j for j in range(n)):
                z2 = i; break
                
        id1 = None
        for i in range(n):
            if all(mul1[i][j] == j and mul1[j][i] == j for j in range(n)):
                id1 = i; break
        id2 = None
        for i in range(n):
            if all(mul2[i][j] == j and mul2[j][i] == j for j in range(n)):
                id2 = i; break
                
        if (z1 is None) != (z2 is None) or (id1 is None) != (id2 is None):
            return True
            
        def solve(mapping, used, i):
            if i == n:
                return True
            for j in range(n):
                if not used[j]:
                    if i == z1 and j != z2: continue
                    if i == id1 and j != id2: continue
                    
                    mapping[i] = j
                    ok = True
                    
                    for k in range(i + 1):
                        if add1[i][k] <= i and mapping[add1[i][k]] != add2[j][mapping[k]]: ok = False; break
                        if mul1[i][k] <= i and mapping[mul1[i][k]] != mul2[j][mapping[k]]: ok = False; break
                        if add1[k][i] <= i and mapping[add1[k][i]] != add2[mapping[k]][j]: ok = False; break
                        if mul1[k][i] <= i and mapping[mul1[k][i]] != mul2[mapping[k]][j]: ok = False; break
                        
                    if ok:
                        for x in range(i):
                            for y in range(i):
                                if add1[x][y] == i and add2[mapping[x]][mapping[y]] != j: ok = False; break
                                if mul1[x][y] == i and mul2[mapping[x]][mapping[y]] != j: ok = False; break
                            if not ok: break
                            
                    if ok:
                        used[j] = True
                        if solve(mapping, used, i + 1):
                            return True
                        used[j] = False
                        
                    mapping[i] = None
            return False
            
        is_iso = solve([None]*n, [False]*n, 0)
        return not is_iso

    try:
        neg_q = check_neg_Q()
    except Exception:
        neg_q = False

    return [h1, h2, neg_q]